def multinomial_mod_p(L):
	n = sum(L)
	if n == 0:
		return 1
	L_sorted = sorted(L)
	accum = 1
	pos = 0
	j = 0
	denom = 1
	while pos < len(L) - 1:
		if denom > L_sorted[pos]:
			denom = 1
			pos += 1
		else:
			accum = accum * (n - j) * invert_mod(denom, p)
			accum %= p
			denom += 1
			j += 1
	return accum

def pow_mod(b, n):
	if n <= 1:
		return b ** n % p
	sqrt = pow_mod(b, n // 2)
	ans = sqrt * sqrt % p
	if n % 2:
		ans = ans * b % p
	return ans

def prod(L):
	return reduce(mul, L, 1)

def fall(x, n):
	accum = 1
	for i in range(x, x - n, -1):
		accum *= i
		accum %= p
	return accum

def fac(n):
	return fall(n, n)

def bezout_solver(a, b):
	if a < b:
		(y, x) = bezout_solver(b, a)
		return (x, y)
	elif b + b == b:
		return (a // a, b - b)
	(q, r) = (a // b, a % b)
	(z, x) = bezout_solver(b, r)
	return (x, z - q * x)

def invert_mod(num, modulus):
	return bezout_solver(modulus, num)[1] % modulus
