		if N <= len(self.smallest_prime_factor) - 1:
			while N != 1:
				factorize[self.smallest_prime_factor[N]] += 1
				N //= self.smallest_prime_factor[N]
		else:
			for p in self.primes:
				while N % p == 0:
					N //= p
					factorize[p] += 1
				if N < p * p:
					if N != 1:
						factorize[N] += 1
					break
				if N <= len(self.smallest_prime_factor) - 1:
					while N != 1:
						factorize[self.smallest_prime_factor[N]] += 1
						N //= self.smallest_prime_factor[N]
					break
			else:
				if N != 1:
					factorize[N] += 1
		return factorize

	def Divisors(self, N):
		assert N > 0
		divisors = [1]
		for (p, e) in self.Factorize(N).items():
			A = [1]
			for _ in range(e):
				A.append(A[-1] * p)
			divisors = [i * j for i in divisors for j in A]
		return divisors

	def Is_Prime(self, N):
		return N == self.smallest_prime_factor[N]

	def Totient(self, N):
		for p in self.Factorize(N).keys():
			N *= p - 1
			N //= p
		return N

class Lucas_Prime:

	def __init__(self, P, e=1, divisible_count=False):
		self.P = P
		self.e = e
		self.divisible_count = divisible_count
		self.mod = self.P ** self.e
		self.factorial = [1]
		for i in range(1, self.mod):
			self.factorial.append(self.factorial[-1])
			if i % P:
				self.factorial[i] *= i
				self.factorial[i] %= self.mod

	def Comb(self, N, K):
		if K < 0 or K > N:
			return 0
		(K0, K1) = (K, N - K)
		N_lst = []
		N_ = N
		while N_:
			N_lst.append(N_ % self.mod)
			N_ //= self.P
		K0_lst = []
		K0_ = K0
		for _ in range(len(N_lst)):
			K0_lst.append(K0_ % self.mod)
			K0_ //= self.P
		K1_lst = []
		K1_ = K1
		for _ in range(len(N_lst)):
			K1_lst.append(K1_ % self.mod)
			K1_ //= self.P
		(retu, retu_rev) = (1, 1)
		for n in N_lst:
			retu *= self.factorial[n]
			retu %= self.mod
		for k0 in K0_lst:
			retu_rev *= self.factorial[k0]
			retu_rev %= self.mod
		for k1 in K1_lst:
			retu_rev *= self.factorial[k1]
			retu_rev %= self.mod
		retu *= MOD(self.mod).Pow(retu_rev, -1)
		if self.P != 2 or self.e <= 2:
			cnt = 0
			N_ = N // self.mod
			K0_ = K0 // self.mod
			K1_ = K1 // self.mod
			while N_:
				cnt += N_
				N_ //= self.P
			while K0_:
				cnt += K0_
				K0_ //= self.P
			while K1_:
				cnt += K1_
				K1_ //= self.P
			if cnt % 2 == 1:
				retu *= -1
		retu %= self.mod
		div_cnt = 0
		(N_, K0_, K1_) = (N, K0, K1)
		while N_:
			div_cnt += N_
			N_ //= self.P
		while K0_:
			div_cnt -= K0_
			K0_ //= self.P
		while K1_:
			div_cnt -= K1_
			K1_ //= self.P
		if self.divisible_count:
			return (retu, div_cnt)
		else:
			retu *= pow(self.P, div_cnt, self.mod)
			retu %= self.mod
			return retu

class Lucas:

	def __init__(self, mod):
		self.mod = mod
		P = Prime(int(self.mod ** 0.5))
		self.factorize = P.Factorize(mod)
		self.L = {p: Lucas_Prime(p, e) for (p, e) in self.factorize.items()}

	def Comb(self, N, K):
		lst_r = []
		lst_m = []
		for (p, e) in self.factorize.items():
			lst_r.append(self.L[p].Comb(N, K))
			lst_m.append(p ** e)
		(r, _) = CRT(lst_r, lst_m)
		return r

def CRT(lst_r, lst_m):
	(r, m) = (lst_r[0], lst_m[0])
	for (r0, m0) in zip(lst_r[1:], lst_m[1:]):
		if (r0, m0) == (-1, 0):
			(r, m) = (-1, 0)
			break
		r0 %= m0
		g = math.gcd(m, m0)
		l = LCM(m, m0)
		if r % g != r0 % g:
			(r, m) = (-1, 0)
			break
		(r, m) = ((r0 + m0 * ((r - r0) // g * Extended_Euclid(m0 // g, m // g)[0] % (m // g))) % l, l)
	return (r, m)
