					self.adj[e[0]][e[1]][3] -= p
					return p
			self.ptr[v] += 1
		return 0

	def calc(self, s, t):
		(flow, self.q[0]) = (0, s)
		for l in range(31):
			while True:
				(self.lvl, self.ptr) = ([0] * len(self.q), [0] * len(self.q))
				(qi, qe, self.lvl[s]) = (0, 1, 1)
