def left_span(arr, n):
	ans = [0]
	span = [0]
	for i in range(1, n):
		while span and arr[i] > arr[span[-1]]:
			span.pop()
		if not span:
			ans.append(0)
		else:
			ans.append(span[-1] + 1)
		span.append(i)
	return ans

def right_span(arr, n):
	ans = [n + 1]
	span = [n - 1]
	for i in range(n - 2, -1, -1):
		while span and arr[i] >= arr[span[-1]]:
			span.pop()
		if not span:
			ans.append(n + 1)
		else:
			ans.append(span[-1] + 1)
		span.append(i)
	return ans[::-1]
