class Solution:

	def findSwapValues(self, a, n, b, m):
		(sum, sum2) = (0, 0)
		for i in range(n):
			sum += a[i]
		for j in range(m):
			sum2 += b[j]
		a.sort()
		b.sort()
		(i, j) = (0, 0)
		while i < n and j < m:
			val = sum - a[i] + b[j]
			val2 = sum2 + a[i] - b[j]
			if val == val2:
				return 1
			if val > val2:
				i += 1
			else:
				j += 1
		return -1

