			dt[arr[i]] = 1
		start = end = ans = 0
		cnt = 0
		for i in range(n):
			if ds.get(arr[i], 0) == 0:
				cnt += 1
			ds[arr[i]] = ds.get(arr[i], 0) + 1
			if cnt == uniq:
