def carryList(k, r, p):
	(kl, rl) = ([], [])
	while k > 0 or r > 0:
		kl.append(k % p)
		rl.append(r % p)
		k = k // p
		r = r // p
	carLi = [(kl[0] + rl[0]) // p]
	for i in range(1, len(kl)):
		carLi.append((carLi[-1] + kl[i] + rl[i]) // p)
	return carLi

def genLucas(n, r, p, q):
	k = n - r
	e = carryList(k, r, p)
	toCarry = sum(e)
	if q <= toCarry:
		return 0
	else:
		toCarryq = sum(e[q - 1:])
		rt = 1
		pr = pow(p, q)
		while n > 0 or r > 0 or k > 0:
			rt *= nFactDict[pr][n % pr] * invList[pr][nFactDict[pr][r % pr]] * invList[pr][nFactDict[pr][k % pr]]
			(n, r, k) = (n // p, r // p, k // p)
		rt *= p ** toCarry * pow(-1, toCarryq)
		return rt % pr

def solve(n, r):
	if n < r:
