def solve(arr, N, Z):
	if Z == 0:
		return 0
	cur = best = sum(arr[-Z:])
	for i in range(1, N - Z + 1):
		cur -= i * (arr[-i] - arr[-i - 1])
		cur += arr[-i - Z]
		if cur < best:
			best = cur
	if Z > 1:
		alternative = arr[0] * N + solve([x - arr[0] for x in arr[1:]], N - 1, Z - 1)
		if alternative < best:
			best = alternative
	return best
