class Solution:

	def Count(self, L, R):
		primes = [1] * (R + 1)
		primes[0] = primes[1] = 0
		p = 2
		while p * p <= R:
			if primes[p]:
				for i in range(p * p, R + 1, p):
					primes[i] = 0
			p += 1
		(cnt, cnt1) = (0, 0)
		for i in range(L, R + 1):
			if primes[i]:
				cnt += 1
			else:
				cnt1 += 1
		if L == 1:
			return cnt1 - cnt - 1
		return cnt1 - cnt

