def eulerSieve(N):
	if N == 1:
		return [0, 1]
	limit = int(N ** 0.5) + 1
	sieve = [0] * (N + 1)
	for i in range(3, limit, 2):
		if sieve[i] == 0:
			for j in range(i * i, N + 1, 2 * i):
				sieve[j] = i
	sieve[0:3] = [0, 1, 1]
	for i in range(3, N + 1):
		p = sieve[i]
		if p != 0:
			j = i // p
			sieve[i] = sieve[j] * (p if j % p == 0 else p - 1)
		elif i & 3 == 0:
			sieve[i] = sieve[i >> 1] << 1
		elif i & 1 == 0:
			sieve[i] = sieve[i >> 1]
		else:
			sieve[i] = i - 1
	return sieve

