class Solution:

	def luckyPermutations(self, N, M, arr, graph):
		ind = defaultdict(list)
		for (i, a) in enumerate(arr):
			ind[a].append(i)
		dp = [[0 for j in range(1 << N)] for i in range(N)]
		for i in range(N):
