class Solution:

	def minTime(self, root, target):
		que = deque()
		parentmap = defaultdict(Node)
		que.append(root)
		start = Node
		while que:
			curr = que.popleft()
			if curr.data == target:
				start = curr
			if curr.left:
				que.append(curr.left)
				parentmap[curr.left] = curr
			if curr.right:
				que.append(curr.right)
				parentmap[curr.right] = curr
		visited = set()
		visited.add(start)
		que.append(start)
		time = 0
		while que:
			size = len(que)
			for _ in range(size):
				curr = que.popleft()
				if curr.left and curr.left not in visited:
					que.append(curr.left)
					visited.add(curr.left)
