class Solution:

	def shortestPath(self, n: int, m: int, edges: List[List[int]]) -> List[int]:
		q = deque()
		ind = {}
		for i in range(n):
			ind[i] = 0
		adj = [[] for i in range(n)]
		for edge in edges:
			adj[edge[0]].append([edge[1], edge[2]])
		for e in edges:
			ind[e[1]] += 1
		for i in ind:
			if ind[i] == 0:
				q.append(i)
		ans = deque()
		while q:
			x = q.popleft()
			ans.append(x)
			for nbr in adj[x]:
				ind[nbr[0]] -= 1
				if ind[nbr[0]] == 0:
					q.append(nbr[0])
		dist = [math.inf] * n
		dist[0] = 0
		while ans:
			node = ans.popleft()
			for e in adj[node]:
				if dist[node] + e[1] < dist[e[0]]:
					dist[e[0]] = dist[node] + e[1]
		for i in range(len(dist)):
			if dist[i] == math.inf:
				dist[i] = -1
		return dist

