class Solution:

	def algo(self, a):
		l = list(a)
		l.sort()
		l1 = l[::-1]
		if len(a) == 1:
			return -1
		if a == l:
			return 0
		if a == l1:
			return 1
		return -1

	def solveQueries(self, nums, q):
		ans = []
		for i in range(len(q)):
			l = q[i]
			if l[0] == 1:
				nums[l[1] - 1] = l[2]
			elif l[0] == 2:
				a = nums[l[1] - 1:l[2]]
				ans.append(self.algo(a))
		return ans

