	def divisors(self, val):
		ans = []
		for i in range(1, int(val ** 0.5) + 1):
			if val % i == 0:
				if val // i == i:
					ans.append(i)
				else:
					ans.append(i)
					ans.append(val // i)
		return ans

	def printPairs(self, a, n, h):
		a.sort()
		count = 0
		_set = set(a)
		k = h
		for i in range(n):
			val = a[i]
			if k in _set and val > k:
				count += 1
			if val >= k:
				arr = self.divisors(val - k)
				for j in arr:
					if j in _set and val % j == k and (val != j):
						count += 1
		return count

