def helpSanta(n, m, g):
	if m == 0:
		return -1
	parent = list(range(n))
	rank = [1] * n

	def find(n):
		if parent[n] != n:
			parent[n] = find(parent[n])
		return parent[n]

	def union(a, b):
		(x, y) = (find(a), find(b))
		if x == y:
			return False
		if rank[x] > rank[y]:
			parent[y] = x
			rank[x] += rank[y]
		else:
			parent[x] = y
			rank[y] += rank[x]
