class Solution:

	def transfigure(self, A, B):
		m = {}
		n = len(A)
		for i in range(n):
			if A[i] in m:
				m[A[i]] += 1
			else:
				m[A[i]] = 1
		for i in range(n):
			if B[i] in m:
				m[B[i]] -= 1
		for key in m:
			if m[key] != 0:
				return -1
		(i, j) = (n - 1, n - 1)
		res = 0
		while i >= 0 and j >= 0:
			while i >= 0 and A[i] != B[j]:
				res += 1
				i -= 1
			i -= 1
			j -= 1
		return res

class Solution:
	hash = {}

	def numTrees(self, n):
		if n == 0:
			return 1
		if n == 1 or n == 2:
			return n
		try:
			return self.hash[n]
		except KeyError:
			pass
		resSum = 0
		for i in range(n):
			tempSum = self.numTrees(i) * self.numTrees(n - (i + 1))
			resSum += tempSum
		self.hash[n] = resSum
		return resSum

