class Solution:

	def removekeys(self, root, l, r):
		if root is None:
			return root
		root.left = self.removekeys(root.left, l, r)
		root.right = self.removekeys(root.right, l, r)
		if root.data > r:
			return root.left
		if root.data < l:
			return root.right
		return root
